import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  const root = new Group();
  const geometry = new PlaneGeometry(1, 1);
  const material = new MeshBasicNodeMaterial({ transparent: true });
  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  const baseY = mesh.position.y;
  const hoverTL = gsap.timeline({ paused: true });
  hoverTL.to(mesh.position, { y: baseY + 0.15, duration: 0.3, ease: 'power2.out' });
  const outTL = gsap.timeline({ paused: true });
  outTL.to(mesh.position, { y: baseY, duration: 0.3, ease: 'power2.out' });

  root.userData.handlers = {
    hover: () => {
      outTL.pause(0);
      hoverTL.play(0);
    },
    pointerout: () => {
      hoverTL.pause(0);
      outTL.play(0);
    },
    click: () => {
      ctx.emit('hub-collection.select', {});
    },
  };

  root.userData.cleanup = () => {
    hoverTL.kill();
    outTL.kill();
    geometry.dispose();
    if (material.map) material.map.dispose();
    material.dispose();
  };

  return root;
}
